let event = msg.payload;

function rejected(reason) {
    node.warn(`Rejected alert: ${reason}`);
    node.status({ fill: "red", shape: "ring", text: reason });
    return [null, null, {
        ...msg,
        payload: {
            valid: false,
            reason,
            received: event
        }
    }];
}

if (Buffer.isBuffer(event)) {
    event = event.toString("utf8");
}
if (typeof event === "string") {
    try {
        event = JSON.parse(event);
    } catch (error) {
        return rejected("invalid JSON");
    }
}
if (!event || typeof event !== "object" || Array.isArray(event)) {
    return rejected("payload is not an object");
}

const topicClass = String(msg.topic || "").split("/").pop();
const expectedTopicClass = {
    fast_consumption: "urgent",
    no_visit_24h: "urgent",
    litter_lacking: "maintenance",
    waste_bin_full: "maintenance"
};
const requiredStrings = [
    "event_id",
    "event_type",
    "alert_type",
    "device_id",
    "qualification_timestamp",
    "notification"
];
for (const field of requiredStrings) {
    if (typeof event[field] !== "string" || !event[field].trim()) {
        return rejected(`missing or invalid ${field}`);
    }
}
if (event.event_type !== "alert_opened") {
    return rejected("event_type must be alert_opened");
}
if (!Object.hasOwn(expectedTopicClass, event.alert_type)) {
    return rejected("unsupported alert_type");
}
if (expectedTopicClass[event.alert_type] !== topicClass) {
    return rejected("alert_type does not match MQTT topic");
}
if (Number.isNaN(Date.parse(event.qualification_timestamp))) {
    return rejected("invalid qualification_timestamp");
}
if (event.alert_type === "no_visit_24h" &&
    (typeof event.pet_name !== "string" || !event.pet_name.trim())) {
    return rejected("no_visit_24h requires pet_name");
}

const deduplicationKey = `${event.event_type}|${event.alert_type}|${event.event_id}`;
const processed = flow.get("processedArchitectureAlertIds") || [];
if (processed.includes(deduplicationKey)) {
    node.status({ fill: "yellow", shape: "ring", text: "duplicate suppressed" });
    return [null, null, {
        ...msg,
        payload: {
            valid: true,
            duplicate: true,
            event
        }
    }];
}
processed.push(deduplicationKey);
flow.set("processedArchitectureAlertIds", processed.slice(-500));

const now = new Date();
const voiceMessage = {
    ...msg,
    event,
    payload: event.notification
};
const auditMessage = {
    ...msg,
    payload: {
        valid: true,
        duplicate: false,
        event
    }
};
const hour = now.getHours();
const quietHours = hour >= 22 || hour < 7;
if (quietHours) {
    const resumeAt = new Date(now);
    resumeAt.setHours(7, 0, 0, 0);
    if (resumeAt <= now) {
        resumeAt.setDate(resumeAt.getDate() + 1);
    }
    voiceMessage.delay = resumeAt.getTime() - now.getTime();
    auditMessage.payload.voice_delivery = "delayed_until_07:00";
    auditMessage.payload.delay_ms = voiceMessage.delay;
    node.status({ fill: "blue", shape: "ring", text: "queued for 07:00" });
    return [null, voiceMessage, auditMessage];
}

auditMessage.payload.voice_delivery = "immediate";
node.status({ fill: "green", shape: "dot", text: event.alert_type });
return [voiceMessage, null, auditMessage];

const now = new Date();
msg.topic = "litter/alerts/urgent";
msg.payload = {
    event_id: `manual-test-${now.getTime()}`,
    event_type: "alert_opened",
    alert_type: "no_visit_24h",
    device_id: "manual-test-device",
    device_name: "Manual Test",
    pet_name: "Cookie",
    qualification_timestamp: now.toISOString(),
    notification: "Test alert. Cookie has not used the litter box in the last 24 hours.",
    evidence: {
        pet_name: "Cookie",
        visit_count: 0,
        window_hours: 24
    },
    source: "node_red_manual_test"
};
return msg;

let data = msg.payload;

if (Buffer.isBuffer(data)) {
    data = data.toString("utf8");
}
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (error) {
        node.warn("Ignored non-JSON MQTT payload");
        return null;
    }
}
if (!data || typeof data !== "object" || Array.isArray(data)) {
    node.warn("Ignored MQTT payload that is not an object");
    return null;
}

const timestampValue = data.timestamp || data.qualification_timestamp;
const timestamp = new Date(timestampValue);
if (Number.isNaN(timestamp.getTime())) {
    node.warn("Ignored message with invalid timestamp");
    return null;
}

const parts = String(msg.topic || "").split("/");
let point;
if (parts[0] === "litter" && parts[1] === "sensor") {
    if (typeof data.metric !== "string" || data.value === null || data.value === undefined) {
        node.warn("Ignored invalid sensor message");
        return null;
    }
    const numericValue = typeof data.value === "boolean"
        ? (data.value ? 1 : 0)
        : Number(data.value);
    if (typeof numericValue === "number" && !Number.isFinite(numericValue)) {
        node.warn("Ignored sensor message with a non-numeric value");
        return null;
    }
    const tags = {
        device_id: String(data.device_id || "unknown"),
        metric: data.metric
    };
    if (parts.length >= 4) {
        tags.pet = parts[2];
    }
    point = {
        measurement: "litter_sensor",
        fields: {
            value: numericValue,
            unit: String(data.unit || "")
        },
        tags,
        timestamp
    };
} else if (parts[0] === "litter" && parts[1] === "alerts") {
    if (typeof data.alert_type !== "string" || typeof data.event_id !== "string") {
        node.warn("Ignored invalid alert message");
        return null;
    }
    const tags = {
        device_id: String(data.device_id || "unknown"),
        alert_type: data.alert_type,
        severity: parts[2] || "unknown"
    };
    if (data.pet_name) {
        tags.pet = String(data.pet_name).toLowerCase();
    }
    point = {
        measurement: "litter_alert",
        fields: {
            active: true,
            event_id: data.event_id,
            notification: String(data.notification || "")
        },
        tags,
        timestamp
    };
} else if (parts[0] === "litter" && parts[1] === "health" && parts[2] === "heartbeat") {
    point = {
        measurement: "litter_heartbeat",
        fields: {
            status: String(data.status || "unknown"),
            history_record_count: `${Number(data.history_record_count) || 0}i`,
            litter_measurement_count: `${Number(data.litter_measurement_count) || 0}i`,
            active_alert_count: `${Array.isArray(data.active_alerts) ? data.active_alerts.length : 0}i`
        },
        tags: {
            device_id: String(data.device_id || "unknown")
        },
        timestamp
    };
} else {
    return null;
}

msg.payload = [point];
msg.influx_measurement = point.measurement;
node.status({ fill: "green", shape: "dot", text: point.measurement });
return msg;

// Forward only real sensor readings to AWS IoT Core as the assessment schema.
let data = msg.payload;
if (Buffer.isBuffer(data)) { data = data.toString("utf8"); }
if (typeof data === "string") {
    try { data = JSON.parse(data); } catch (e) { return null; }
}
if (!data || typeof data !== "object" || Array.isArray(data)) { return null; }

const parts = String(msg.topic || "").split("/");
// Only litter/sensor/... messages (skip alerts and heartbeat)
if (parts[0] !== "litter" || parts[1] !== "sensor") { return null; }
if (typeof data.metric !== "string" || data.value === null || data.value === undefined) { return null; }

// Boolean sensors (box_full, sand_lack) -> 1/0, consistent with InfluxDB storage
const value = typeof data.value === "boolean" ? (data.value ? 1 : 0) : Number(data.value);
if (!Number.isFinite(value)) { return null; }

// Pet-scoped topics (litter/sensor/cookie/visit_rate) -> sensor name includes the pet
const sensorName = parts.length >= 4 ? parts[2] + "_" + data.metric : data.metric;

const out = {
    device_id: String(data.device_id || "petkit_pura_x"),
    sensor: sensorName,
    value: value,
    timestamp: data.timestamp || new Date().toISOString()
};

msg.payload = JSON.stringify(out);
msg.topic = "cps/sensor/data";
node.status({ fill: "blue", shape: "dot", text: sensorName + "=" + value });
return msg;

// Forward only alert messages to the cloud, preserving urgent/maintenance split.
  const parts = String(msg.topic || "").split("/");

  // Keep only litter/alerts/... (skip sensors and heartbeat)
  if (parts[0] !== "litter" || parts[1] !== "alerts") {
      return null;
  }

  const severity = parts[2] || "general";   // "urgent" or "maintenance"
  msg.topic = "cps/alerts/" + severity;      // -> cps/alerts/urgent or cps/alerts/maintenance

  // MQTT out needs a string payload
  if (typeof msg.payload !== "string") {
      msg.payload = JSON.stringify(msg.payload);
  }

  node.status({ fill: "yellow", shape: "dot", text: "alert -> " + msg.topic });
  return msg;

// Validates litter/sensor/* readings before storage and cloud publishing.
// Output 1: accepted readings (and every non-sensor message, unchanged).
// Output 2: rejected readings with a reason, for the event log.
const RULES = {
    sand_percent: { min: 0, max: 100 },
    box_full: { boolean: true },
    sand_lack: { boolean: true },
    visit_rate: { min: 0, max: 50 },
    avg_duration: { min: 0, max: 1800 }
};

const parts = String(msg.topic || "").split("/");
if (parts[0] !== "litter" || parts[1] !== "sensor") {
    return [msg, null];
}

function reject(reason) {
    const count = (context.get("rejected") || 0) + 1;
    context.set("rejected", count);
    node.status({ fill: "red", shape: "ring", text: `rejected ${count}: ${reason}` });
    return [null, { topic: msg.topic, payload: msg.payload, log_status: "rejected", log_reason: reason }];
}

let data = msg.payload;
if (Buffer.isBuffer(data)) {
    data = data.toString("utf8");
}
if (typeof data === "string") {
    try {
        data = JSON.parse(data);
    } catch (error) {
        return reject("payload is not valid JSON");
    }
}
if (!data || typeof data !== "object" || Array.isArray(data)) {
    return reject("payload is not an object");
}

const rule = RULES[data.metric];
if (!rule) {
    return reject(`unknown metric ${data.metric}`);
}
if (data.value === null || data.value === undefined || data.value === "") {
    return reject("missing value");
}
if (Number.isNaN(new Date(data.timestamp).getTime())) {
    return reject("missing or invalid timestamp");
}

if (rule.boolean) {
    if (![true, false, 0, 1].includes(data.value)) {
        return reject(`expected true/false, got ${data.value}`);
    }
} else {
    const value = Number(data.value);
    if (!Number.isFinite(value)) {
        return reject(`not a number: ${data.value}`);
    }
    if (value < rule.min || value > rule.max) {
        return reject(`out of range: ${value} outside ${rule.min}-${rule.max}`);
    }
}

const accepted = (context.get("accepted") || 0) + 1;
context.set("accepted", accepted);
node.status({ fill: "green", shape: "dot", text: `accepted ${accepted}, rejected ${context.get("rejected") || 0}` });
msg.payload = data;
return [msg, null];

// 5-point moving average of the litter level, stored alongside the raw value
// as metric sand_percent_smoothed. Every message passes through unchanged.
const WINDOW = 5;

if (msg.topic !== "litter/sensor/sand_percent") {
    return msg;
}

const data = msg.payload;
const key = `history_${data.device_id}`;
const history = context.get(key) || [];
history.push(Number(data.value));
while (history.length > WINDOW) {
    history.shift();
}
context.set(key, history);

const mean = history.reduce((sum, value) => sum + value, 0) / history.length;
const smoothedValue = Math.round(mean * 10) / 10;
node.status({ fill: "blue", shape: "dot", text: `raw ${data.value}%, avg ${smoothedValue}% (n=${history.length})` });

const smoothed = {
    topic: "litter/sensor/sand_percent_smoothed",
    payload: {
        ...data,
        metric: "sand_percent_smoothed",
        value: smoothedValue,
        window_size: history.length
    }
};
return [[msg, smoothed]];

// Formats every accepted reading, rejected reading, and alert decision as one
// JSON line for the event log file.
const isAlert = String(msg.topic || "").startsWith("litter/alerts");
const entry = {
    logged_at: new Date().toISOString(),
    status: msg.log_status || (isAlert ? "alert" : "accepted"),
    topic: msg.topic,
    reason: msg.log_reason,
    payload: msg.payload
};
return { payload: JSON.stringify(entry) };
